import os
from pathlib import Path
import runpy
import shutil
import sys
import uuid


def fail(message):
    print(message, file=sys.stderr)
    raise SystemExit(2)


def digest_tree(root, plugin):
    excluded = {\x22hooks/codex.json\x22}
    if plugin == \x22machine\x22:
        excluded.add(\x22catalog/catalog.json\x22)
    digest = hashlib.sha256()
    for path in sorted(root.rglob(\x22*\x22), key=lambda item: item.relative_to(root).as_posix()):
        if path.is_symlink():
            fail(\x22Codex hook package contains a symbolic link\x22)
        if path.is_dir():
            continue
        if not path.is_file():
            fail(\x22Codex hook package contains an unsupported entry\x22)
        relative = path.relative_to(root).as_posix()
        if relative in excluded:
            continue
        content = path.read_bytes()
        try:
            text = content.decode(\x22utf-8\x22)
        except UnicodeDecodeError:
            pass
        else:
            content = text.replace(\x22\r\n\x22, \x22\n\x22).replace(\x22\r\x22, \x22\n\x22).encode(\x22utf-8\x22)
        digest.update(relative.encode(\x22utf-8\x22))
        digest.update(b\x22\0\x22)
        digest.update(str(len(content)).encode(\x22ascii\x22))
        digest.update(b\x22\0\x22)
        digest.update(content)
    return \x22sha256:\x22 + digest.hexdigest()


def verified(root, expected, plugin):
    if not root.is_dir() or root.is_symlink() or digest_tree(root, plugin) != expected:
        fail(\x22Codex hook package integrity check failed\x22)


def main():
    root = Path(sys.argv[1])
    expected = sys.argv[2]
    plugin = sys.argv[3]
    script = Path(sys.argv[4])
    relative = script.relative_to(root)
    if root.parent.name != plugin or relative.is_absolute() or \x22..\x22 in relative.parts:
        fail(\x22Codex hook package identity is invalid\x22)
    data = os.environ.get(\x22PLUGIN_DATA\x22)
    if not data:
        fail(\x22Codex hook data directory is unavailable\x22)
    snapshot_dir = Path(data).resolve() / \x22hook-snapshots\x22
    key = hashlib.sha256(str(root).encode(\x22utf-8\x22)).hexdigest()
    snapshot = snapshot_dir / key
    if not snapshot.is_dir():
